ST.xhtml:
TEST('AnyLongString');
IF NOT IS_TEST_FINISHED('AnyLongString') THEN
	_longE := 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
	_longA := 'xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx';
	AssertEquals(Expected := _longE, Actual := _longA, Message := 'long-string');
	TEST_FINISHED();
END_IF

TEST('AnyLongWString');
IF NOT IS_TEST_FINISHED('AnyLongWString') THEN
	_wideE := "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx";
	_wideA := "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx";
	AssertEquals(Expected := _wideE, Actual := _wideA, Message := 'long-wstring');
	TEST_FINISHED();
END_IF

TEST('AnyTypeMismatch');
IF NOT IS_TEST_FINISHED('AnyTypeMismatch') THEN
	AssertEquals(Expected := _uint, Actual := _udint, Message := 'AnyTypeMismatch');
	TEST_FINISHED();
END_IF

TEST('AnyRepresentationEqual');
IF NOT IS_TEST_FINISHED('AnyRepresentationEqual') THEN
	_userE.A := 1;
	_userE.B := 2;
	_userA := _userE;
	AssertEquals(Expected := _userE, Actual := _userA, Message := 'same-representation');
	TEST_FINISHED();
END_IF

TEST('AnyRepresentationDifferent');
IF NOT IS_TEST_FINISHED('AnyRepresentationDifferent') THEN
	_userE.A := 1;
	_userE.B := 2;
	_userA := _userE;
	_userA.B := 3;
	AssertEquals(Expected := _userE, Actual := _userA, Message := 'AnyRepresentationDifferent');
	TEST_FINISHED();
END_IF

TEST('StringThenReal');
IF NOT IS_TEST_FINISHED('StringThenReal') THEN
	_regressionScan := _regressionScan + 1;
	IF _regressionScan = 1 THEN
		AssertEquals_STRING(Expected := 'text-first', Actual := 'different', Message := 'first-string');
	ELSE
		AssertEquals_REAL(Expected := 1.0, Actual := 2.0, Delta := 0.0, Message := 'later-real');
		TEST_FINISHED();
	END_IF
END_IF

TEST('ArrayDifferentLowerBounds');
IF NOT IS_TEST_FINISHED('ArrayDifferentLowerBounds') THEN
	AssertArrayEquals_UINT(Expecteds := _arrayE, Actuals := _arrayA, Message := 'lower-bounds');
	TEST_FINISHED();
END_IF

TEST('ArrayDifferentLengths');
IF NOT IS_TEST_FINISHED('ArrayDifferentLengths') THEN
	AssertArrayEquals_UINT(Expecteds := _arrayE, Actuals := _arrayLong, Message := 'ArrayDifferentLengths');
	TEST_FINISHED();
END_IF

